ALTER TABLE `Event` ADD COLUMN `paymentMode` VARCHAR(191) NOT NULL DEFAULT 'ORGANIZER_QR';
CREATE TABLE `SimulationAttempt` (`id` VARCHAR(191) NOT NULL,`idempotencyKey` VARCHAR(191) NOT NULL,`reference` VARCHAR(191) NOT NULL,`paymentId` VARCHAR(191) NOT NULL,`refundId` VARCHAR(191) NULL,`kind` VARCHAR(191) NOT NULL,`outcome` VARCHAR(191) NOT NULL,`testOnly` BOOLEAN NOT NULL DEFAULT true,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`),UNIQUE INDEX `SimulationAttempt_idempotencyKey_key` (`idempotencyKey`),UNIQUE INDEX `SimulationAttempt_reference_key` (`reference`),INDEX `SimulationAttempt_paymentId_kind_outcome_idx` (`paymentId`,`kind`,`outcome`),CONSTRAINT `SimulationAttempt_paymentId_fkey` FOREIGN KEY (`paymentId`) REFERENCES `Payment`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
